llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C17"],
      "claim": "Lycopene, a highly lipophilic long-chain isoprenoid structurally analogous to the query's polyprenyl tail, showed only 0.17% systemic availability after oral ingestion in humans, directly supporting F<20% for this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In a separate human study, lycopene capsules yielded ~2.6% bioavailability, reinforcing that large lipophilic isoprenoids are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Synthetic lycopene dispersed in oil gave ~1.2% systemic availability, indicating that even lipid-based formulation does not overcome the poor absorption of this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "One lycopene study reported 23.2% ± 8% bioavailability for all-trans lycopene, an outlier among lycopene records; its low transfer score and methodological differences limit its weight, but it is contradictory to a low prediction.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Finerenone, a small drug-like molecule, had 43.5% absolute oral bioavailability in humans; despite a high assay-transfer score, its small size and moderate lipophilicity are not chemically representative of the query's extreme MW/logP, so this high-F evidence is not transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C44"],
      "claim": "BI 425809, another small molecule, showed 71.64% absolute bioavailability in fasted humans; high assay-transfer but low chemical analogy to the query limits its relevance.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is coenzyme Q10, an extremely lipophilic, high-molecular-weight polyprenyl quinone. The most chemically relevant evidence—lycopene, a long-chain isoprenoid—shows very low oral systemic availability in humans (0.17–2.6%), supporting F<20%. The high assay-transfer small-molecule records with F>20% are not chemically transferable because they lack the query's extreme size and lipophilicity. The physicochemical prior also predicts poor absorption. Therefore, predict low.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for coenzyme Q10 itself; the closest structural analogue (lycopene) has low assay-transfer score and mixed results.",
    "The high-transfer small-molecule records are not chemically analogous to the query's extreme lipophilicity and high molecular weight, so their F>20% values cannot be directly extrapolated.",
    "Formulation effects (e.g., lipid-based or solubilized CoQ10) are not represented in the evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

